RUNS=$S/runs/project-workflows
RUN=$RUNS/project-workflows-001
cd "$REPO"
echo "== export version before: $(python3 -c "import json;print(json.load(open('$RUN/run-state.json'))['version'])")"
$PY -m workflow export "$RUN"
echo "== export version after: $(python3 -c "import json;print(json.load(open('$RUN/run-state.json'))['version'])")"
python3 - "$RUN" <<'PYEOF'
import json, sys
