echo "== inputs"
curl -fs "$BASE/inputs" | python3 -c "import json,sys;r=json.load(sys.stdin);print(r['feature'], r['mode'], r['automatic']);[print(' -', w['node_id'], w['launch_node_id'], 'task', len(w['task']['text']), 'prompt', bool(w['prompt']), 'launch', w['launch'] and w['launch']['session_id'][:8], 'completion', w['completion'] and w['completion']['status'], 'stop', w['stop']) for w in r['workers']]"
echo "== absolute paths in payloads?"
